BEGIN;
ALTER TABLE direction_criterion DROP CONSTRAINT criterion_metric;
ALTER TABLE direction_criterion ADD CONSTRAINT criterion_metric CHECK (metric IN ('MANUAL','WORK_SOURCE_INCOME','BUSINESS_RECEIPTS','NEW_RECURRING_COMPANY','CONVERSATIONS','CONVERSATION_COMPANIES','CONVERSATION_PEOPLE','SESSION_TIME','ENGINEERING_EVIDENCE','ENGINEERING_PROJECT_COMPLETED','SAVINGS_GOAL','CONTENT_CREATED','CONTENT_VARIANTS_CREATED','CONTENT_PUBLICATIONS'));
ALTER TABLE direction_criterion DROP CONSTRAINT criterion_outreach_scope;
ALTER TABLE direction_criterion ADD CONSTRAINT criterion_outreach_scope CHECK (NOT "selectedOutreachOnly" OR ("experimentId" IS NOT NULL AND metric IN ('CONVERSATIONS','CONVERSATION_COMPANIES','CONVERSATION_PEOPLE')));
ALTER TABLE direction_criterion ADD CONSTRAINT criterion_market_type CHECK ("marketType" IN ('UNKNOWN','B2C','B2B','BOTH'));
COMMIT;
